/* Emberwild — gather by day, forge with shadow drops, face the Hollow King. */
(() => {
'use strict';
const $=id=>document.getElementById(id), canvas=$('world'), ctx=canvas.getContext('2d');
const W=4800, GROUND=540, CAMP=470, ALTAR=4560, DAY=90, NIGHT=45, SAVE='emberwild-v1';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rand=(a,b)=>a+Math.random()*(b-a);
const near=(a,b,r)=>Math.abs(a-b)<r;
let viewW=1180,viewH=520,scale=1,camera=0,anim=0,last=0,saveTime=0,spawnTime=5;
let playing=false,paused=false,ended=false,dialogPause=false,sound=false,audio;
let state,particles=[],floaters=[],enemies=[],loot=[],projectiles=[],fireworks=[],toastTime=0,restartArmed=false;
let celebration=false,fireworkTimer=0,inventorySignature='';
let keys={left:false,right:false,jump:false,action:false},jumpBuffer=0,coyote=0;
const terrain=[{x:0,y:540,w:1250,h:600},{x:1390,y:540,w:990,h:600},{x:2530,y:540,w:920,h:600},{x:3610,y:540,w:1190,h:600},
{x:740,y:435,w:170,h:26},{x:1010,y:355,w:170,h:26},{x:1290,y:285,w:170,h:26},{x:1550,y:405,w:190,h:26},{x:1820,y:315,w:180,h:26},{x:2110,y:405,w:180,h:26},{x:2380,y:300,w:170,h:26},{x:2660,y:410,w:180,h:26},{x:2940,y:325,w:190,h:26},{x:3250,y:410,w:170,h:26},{x:3490,y:305,w:170,h:26},{x:3780,y:415,w:180,h:26},{x:4050,y:320,w:200,h:26},{x:4390,y:410,w:200,h:26}];
const resources=[];
function addResource(type,x,y=GROUND){const uses=type==='wood'||type==='stone'?3:type==='iron'?2:1;resources.push({id:resources.length,type,x,y,uses,left:uses,flash:0});}
[190,690,930,1130,1490,1690,1970,2260,2650,2810,3120,3350,3740,3970,4300,4640].forEach(x=>addResource('wood',x));
[310,820,1080,1560,2040,2200,2740,3000,3300,3850,4190,4510].forEach(x=>addResource('stone',x));
[590,990,1770,2170,2880,3220,4090,4420].forEach(x=>addResource('berry',x));
terrain.slice(4).forEach((p,i)=>{if(i%2===1||i===0)addResource('crystal',p.x+p.w/2,p.y);});
// Append deposits so saves from the first release retain their resource IDs.
[1190,1620,2320,2590,3090,3890,4250].forEach(x=>addResource('iron',x));
addResource('iron',1880,315);addResource('iron',4150,320);
const weapons={axe:{name:'Woodcutter’s axe',damage:22,cool:.46,reach:75},sword:{name:'Iron sword',damage:38,cool:.32,reach:94},duskblade:{name:'Duskblade',damage:68,cool:.30,reach:110}};
const items={wood:['▰','Wood','From trees. Build camp and fuel the fire.'],stone:['⬟','Stone','From rocks. For shelter, tools, and a forge.'],crystal:['◆','Crystal','On high platforms. Double-jump to reach it.'],iron:['▧','Iron ore','Mine copper-coloured veins with your axe.'],essence:['✧','Shadow essence','Dropped by defeated night shadows. Walk over it to collect.'],berry:['●','Berries','Stored until you choose to eat. Each heals 25 health.']};
function fresh(){return {v:2,player:{x:410,y:480,vx:0,vy:0,dir:1,hp:100,jumps:0,inv:0,cool:0,swing:0},bag:{wood:0,stone:0,crystal:0,iron:0,essence:0,berry:3},equipped:'axe',day:1,time:0,night:false,nights:0,fuel:70,shelter:false,axe:false,sword:false,duskblade:false,armor:false,charm:false,forge:false,beacon:false,bossUnlocked:false,boss:null,kills:0,resources:[],bridges:[],loot:[]};}
function migrate(s){const base=fresh();return {...base,...s,v:2,player:{...base.player,...s.player},bag:{...base.bag,...s.bag},equipped:weapons[s.equipped]?s.equipped:'axe',bossUnlocked:!!s.bossUnlocked||s.nights>=3,loot:s.loot||[]};}
function save(){if(!playing||ended)return;try{state.resources=resources.map(r=>r.left);state.loot=loot;localStorage.setItem(SAVE,JSON.stringify(state));$('saved').textContent='Adventure saved';}catch{$('saved').textContent='Saving unavailable';}}
function readSave(){try{const s=JSON.parse(localStorage.getItem(SAVE));if(s&&(s.v===1||s.v===2)&&s.player&&s.bag&&Array.isArray(s.resources)&&Array.isArray(s.bridges)&&Number.isFinite(s.player.x)&&Number.isFinite(s.day)&&s.day>=1&&s.player.hp>0)return migrate(s);}catch{}return null;}
function init(s){state=s?migrate(s):fresh();resources.forEach((r,i)=>{r.left=s?(s.resources[i]??r.uses):r.uses;r.flash=0;});particles=[];floaters=[];enemies=[];projectiles=[];fireworks=[];loot=state.loot||[];celebration=false;spawnTime=3;jumpBuffer=0;coyote=0;state.player.vx=0;state.player.vy=0;state.player.inv=2;camera=clamp(state.player.x-viewW*.38,0,Math.max(0,W-viewW));playing=true;paused=false;ended=false;keys={};for(const id of ['intro','endOverlay','pauseOverlay','buildOverlay','inventoryOverlay'])$(id).hidden=true;$('pause').textContent='Ⅱ';$('context').dataset.key='reset';updateUI();notify(s?'Welcome back. Your gear and materials are safe.':'Gather supplies. Forge a sword. Night one is coming.');save();}
function notify(msg){$('toast').textContent=msg;toastTime=3.6;$('toast').classList.add('show');}
function beep(freq=200,dur=.06,type='sine',vol=.025){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.5),audio.currentTime+dur);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}catch{}}
function puff(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-65,65),vy:rand(-110,-20),life:rand(.3,.7),color,size:rand(2,5)});}
function floater(x,y,text,color='#ffe1a2'){floaters.push({x,y,text,color,life:1.2});}
function allTerrain(){return terrain.concat(state.bridges.map(x=>({x,y:540,w:160,h:16,bridge:true})));}
function moveBody(b,dt,w,h){const oldY=b.y;b.vy+=1150*dt;b.x=clamp(b.x+b.vx*dt,12,W-w-12);b.y+=b.vy*dt;let grounded=false;for(const p of allTerrain()){if(b.vy>=0&&oldY+h<=p.y+3&&b.y+h>=p.y&&b.x+w>p.x&&b.x<p.x+p.w){b.y=p.y-h;b.vy=0;grounded=true;}}return grounded;}
function getNearby(){const p=state.player;return resources.filter(r=>r.left>0&&Math.abs(r.x-(p.x+13))<77&&Math.abs(r.y-(p.y+40))<65).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];}
function equippedWeapon(){const w=state.equipped==='axe'||state[state.equipped]?state.equipped:'axe';const base=weapons[w];return {...base,damage:base.damage+(w==='axe'&&state.axe?10:0)};}
function equip(id){if(!playing||ended||!weapons[id]||(id!=='axe'&&!state[id]))return;state.equipped=id;updateUI();renderInventory();save();beep(390,.08);}
function swapWeapon(){if(!playing||ended)return;equip(state.equipped==='axe'?(state.duskblade?'duskblade':state.sword?'sword':'axe'):'axe');if(!state.sword&&!state.duskblade)notify('Forge an iron sword at camp to unlock weapon swapping.');}
function dropShadow(e){if(e.dead)return;e.dead=true;state.kills++;let x=e.x+15,y=e.y+15;if(y>580){const bank=terrain.slice(0,4).find(t=>x>=t.x&&x<=t.x+t.w);if(!bank){const edges=terrain.slice(0,4).map(t=>clamp(x,t.x+20,t.x+t.w-20));x=edges.reduce((a,b)=>Math.abs(b-x)<Math.abs(a-x)?b:a);}y=510;}loot.push({type:'essence',count:e.brute?3:2,x,y,vy:-100});loot.push({type:'berry',count:1,x:x+13,y,vy:-80});floater(x,y-25,e.brute?'Heavy shadow defeated':'Shadow defeated','#b9c9ed');puff(x,y,'#b4a6d3',10);beep(420,.12);}
function doAction(){if(!playing||paused||ended)return;const p=state.player;if(p.cool>0)return;const weapon=equippedWeapon();p.cool=weapon.cool;p.swing=.22;beep(state.equipped==='axe'?210:370,.06,'triangle');let hit=false;
for(const e of enemies){if(e.hp>0&&Math.abs((e.x+15)-(p.x+13))<weapon.reach&&Math.abs(e.y-p.y)<65){e.hp-=weapon.damage;e.stun=.18;e.x=clamp(e.x+p.dir*16,0,W-30);puff(e.x+15,e.y+15,'#a3c2b6',7);hit=true;if(e.hp<=0)dropShadow(e);}}
enemies=enemies.filter(e=>e.hp>0);const b=state.boss;if(b&&b.hp>0&&Math.abs((b.x+42)-(p.x+13))<weapon.reach+24&&p.y+44>b.y&&p.y<b.y+110){b.hp=Math.max(0,b.hp-weapon.damage);puff(b.x+40,b.y+45,'#d0b5e1',12);hit=true;if(b.hp<=0){state.bossDefeated=true;finish(true);return;}}
if(hit){updateUI();return;}const r=getNearby();if(!r)return;if(state.equipped!=='axe'&&r.type!=='berry'&&r.type!=='crystal'){notify('Equip your axe to gather wood, stone, and ore.');return;}r.left--;r.flash=.22;const n=r.type==='wood'?3:r.type==='stone'||r.type==='iron'?2:r.type==='berry'?3:1;state.bag[r.type]+=n;p.dir=r.x<p.x?-1:1;puff(r.x,r.y-30,r.type==='iron'?'#dfb595':r.type==='crystal'?'#a3e4cf':r.type==='berry'?'#ce8c8d':'#c4b98b');floater(r.x,r.y-60,`+${n} ${r.type==='iron'?'iron ore':r.type}`);beep(r.type==='crystal'?720:310,.09);updateUI();}
function jump(){if(!playing||paused||ended)return;jumpBuffer=.14;}
function eat(){if(!playing||ended||(paused&&$('inventoryOverlay').hidden))return;if(state.bag.berry<1){notify('Pick berry bushes or collect food dropped by shadows.');return;}if(state.player.hp>=100){notify('Health is full. Your berries stay safely in the bag.');return;}state.bag.berry--;state.player.hp=Math.min(100,state.player.hp+25);floater(state.player.x,state.player.y-10,'+25 health','#b5dda1');beep(520,.14);updateUI();if(!$('inventoryOverlay').hidden)renderInventory();save();}
function hurt(amount){const p=state.player;if(p.inv>0||ended)return;const damage=Math.ceil(amount*(state.armor?.6:1)*(state.shelter&&near(p.x,CAMP,150)&&!state.boss?.75:1));p.hp=Math.max(0,p.hp-damage);p.inv=.85;puff(p.x+12,p.y+20,'#d9987e',9);beep(95,.2,'sawtooth',.025);if(p.hp<=0)finish(false);}
function finish(won){if(ended)return;if(won&&!state.bossDefeated)return;ended=true;paused=true;celebration=won;fireworkTimer=0;keys={};try{localStorage.removeItem(SAVE);}catch{}$('endLabel').textContent=won?'THE HOLLOW KING HAS FALLEN':'THE FOREST KEEPS ITS SECRETS';$('endTitle').textContent=won?'I’m so proud of you.':'A spark is never the end.';$('endCopy').textContent=won?`You braved ${state.nights} nights, forged your own strength, and defeated the Hollow King. You kept going, even when it got hard. Look what you made possible.`:`You made it to ${state.boss?'the Hollow King':`${state.night?'night':'day'} ${state.day}`}. Save berries, upgrade your sword, and turn shadow essence and iron ore into stronger gear.`;$('again').textContent=won?'Begin a new adventure →':'Try another adventure →';$('endOverlay').hidden=false;if(won){launchFirework(viewW*.2,viewH*.22);launchFirework(viewW*.8,viewH*.25);launchFirework(viewW*.5,viewH*.14);}$('toast').classList.remove('show');updateUI();}
function anyMenu(){return !$('buildOverlay').hidden||!$('inventoryOverlay').hidden;}
function togglePause(force){if(!playing||ended||anyMenu())return;paused=typeof force==='boolean'?force:!paused;$('pauseOverlay').hidden=!paused;$('pause').textContent=paused?'▶':'Ⅱ';keys={};if(paused)save();}
const recipes=[
{id:'fuel',name:'Feed the fire',desc:'+40 fuel · a little safety after dark',cost:{wood:2}},
{id:'shelter',name:'Forest shelter',desc:'Heal at camp · reduce nearby damage',cost:{wood:8,stone:4}},
{id:'forge',name:'Camp forge',desc:'Unlock swords, shadowmail, and wardcraft',cost:{wood:4,stone:6}},
{id:'sword',name:'Iron sword',desc:'38 damage · faster, longer attacks',cost:{wood:3,iron:4},forge:true},
{id:'axe',name:'Sharpened axe',desc:'32 damage · keep a gathering tool handy',cost:{wood:4,stone:4}},
{id:'duskblade',name:'Duskblade',desc:'68 damage · required for the final challenge',cost:{iron:8,essence:6,crystal:2},forge:true},
{id:'armor',name:'Shadowmail',desc:'40% less damage · required for the final challenge',cost:{iron:6,essence:4},forge:true},
{id:'charm',name:'Moonward charm',desc:'Halves the boss’s projectile damage',cost:{crystal:3,essence:3},forge:true},
{id:'beacon',name:'Crystal beacon',desc:'A wider circle of shadow-burning firelight',cost:{wood:6,stone:6,crystal:3}}
];
function canAfford(cost){return Object.entries(cost).every(([k,v])=>state.bag[k]>=v);}
function renderRecipes(){const root=$('recipes');root.replaceChildren();for(const r of recipes){const built=r.id!=='fuel'&&state[r.id];const row=document.createElement('div');row.className='recipe';const info=document.createElement('div');const name=document.createElement('strong');name.textContent=r.name;const desc=document.createElement('small');desc.textContent=r.desc;const cost=document.createElement('small');cost.textContent=Object.entries(r.cost).map(([k,v])=>`${v} ${k==='iron'?'iron ore':k==='essence'?'shadow essence':k}`).join(' · ');info.append(name,desc,cost);const btn=document.createElement('button');btn.textContent=built?'Built ✓':r.forge&&!state.forge?'Forge first':r.id==='fuel'?'Refuel +40':'Craft';btn.disabled=built||!canAfford(r.cost)||(r.forge&&!state.forge)||(r.id==='fuel'&&state.fuel>=100);btn.onclick=()=>craft(r.id);row.append(info,btn);root.append(row);}}
function openBuild(){if(!playing||ended||state.boss)return;if(Math.abs(state.player.x-CAMP)>200||state.player.y<400){notify('Return to the campfire to build and forge gear.');return;}paused=true;keys={};$('buildOverlay').hidden=false;renderRecipes();}
function craft(id){const r=recipes.find(r=>r.id===id);if(!r||!canAfford(r.cost)||(id!=='fuel'&&state[id])||(r.forge&&!state.forge)||(id==='fuel'&&state.fuel>=100))return;for(const [k,v]of Object.entries(r.cost))state.bag[k]-=v;if(id==='fuel')state.fuel=Math.min(100,state.fuel+40);else state[id]=true;if(id==='sword'||id==='duskblade')state.equipped=id;beep(570,.2,'triangle');$('campHint').textContent=id==='fuel'?'The fire burns a little brighter.':`${r.name} ready. ${id==='armor'?'Equipped automatically.':id==='duskblade'?'Your blade is ready for the King.':'A good day’s work.'}`;updateUI();renderRecipes();save();}
function closeBuild(){$('buildOverlay').hidden=true;paused=false;keys={};}
function renderInventory(){const root=$('bagItems');root.replaceChildren();for(const [id,[icon,name,desc]]of Object.entries(items)){const row=document.createElement('div');row.className='bag-item';const title=document.createElement('strong');title.textContent=`${icon} ${name} · ${state.bag[id]}`;const note=document.createElement('small');note.textContent=desc;row.append(title,note);root.append(row);}const rack=$('weaponRack');rack.replaceChildren();for(const [id,w]of Object.entries(weapons)){const btn=document.createElement('button');btn.className='weapon-card'+(state.equipped===id?' selected':'');btn.disabled=id!=='axe'&&!state[id];btn.textContent=`${id==='axe'?'⚒':'†'} ${w.name} · ${id==='axe'&&state.axe?32:w.damage} damage${state.equipped===id?' · equipped':btn.disabled?' · craft at camp':''}`;btn.onclick=()=>equip(id);rack.append(btn);}$('armorStatus').textContent=`${state.armor?'✓ Shadowmail equipped · 40% damage reduction':'○ Shadowmail · needs 6 iron ore + 4 shadow essence'}${state.charm?' · ✓ Moonward charm':''}`;$('bagEat').disabled=state.bag.berry<1||state.player.hp>=100;$('bagEat').textContent=`Eat a berry · ${state.bag.berry} saved · +25 health`;$('bossChecklist').textContent=`FINAL CHALLENGE  ${state.nights>=3?'✓':'○'} Survive three nights  ${state.duskblade?'✓':'○'} Duskblade  ${state.armor?'✓':'○'} Shadowmail`;}
function openInventory(){if(!playing||ended||!$('buildOverlay').hidden)return;paused=true;keys={};$('inventoryOverlay').hidden=false;renderInventory();}
function closeInventory(){$('inventoryOverlay').hidden=true;paused=false;keys={};}
function bridge(){if(!playing||paused||ended||state.boss)return;const p=state.player;const gap=[1250,2380,3450].find(x=>Math.abs(p.x-x)<150&&!state.bridges.includes(x));if(gap===undefined){notify('Stand near a ravine to build a bridge.');return;}if(state.bag.wood<3){notify('A bridge needs 3 wood. You can also double-jump the gap.');return;}state.bag.wood-=3;state.bridges.push(gap);puff(gap,540,'#b49b68',15);notify('Bridge built. A safer way home.');updateUI();save();}
function spawnShadow(x){const tier=state.day,brute=tier>=2&&Math.random()<Math.min(.5,.15*tier);const maxHp=68+16*tier+(brute?36:0);const e={x:x??clamp(state.player.x+(Math.random()<.5?-1:1)*rand(430,650),30,W-50),y:300,vx:0,vy:0,hp:maxHp,maxHp,attack:0,seed:Math.random()*10,brute,damage:14+2*tier+(brute?4:0),speed:72+12*tier,dash:rand(3,5),windup:0,dashTime:0,dashDir:1,stun:0};enemies.push(e);return e;}
function collectLoot(dt){const p=state.player;for(const l of loot){l.vy=(l.vy||0)+300*dt;l.y=Math.min(520,l.y+l.vy*dt);if(l.y>=520)l.vy=0;if(Math.hypot(l.x-(p.x+13),l.y-(p.y+25))<67){state.bag[l.type]+=l.count;l.taken=true;floater(l.x,l.y-15,`+${l.count} ${l.type==='essence'?'shadow essence':'berry'}`,l.type==='essence'?'#cab1ec':'#e4b2a9');beep(560,.05);}}loot=loot.filter(l=>!l.taken);}
function summonBoss(){if(!playing||paused||ended||state.boss)return;if(!state.bossUnlocked){notify('Survive three nights to awaken the altar.');return;}if(!near(state.player.x,ALTAR,170)||state.player.y<420){notify('The Hollow King waits at the altar in the Far Pines.');return;}if(!state.duskblade||!state.armor){notify('Forge a Duskblade and Shadowmail using iron ore + shadow essence.');return;}state.equipped='duskblade';state.night=false;state.player.x=4250;state.player.y=496;state.player.hp=100;state.player.inv=2;enemies=[];projectiles=[];camera=clamp(state.player.x-viewW*.4,0,Math.max(0,W-viewW));state.boss={x:4400,y:430,vx:0,vy:0,hp:1500,maxHp:1500,phase:1,timer:2.3,mode:'stalk',tell:0,attackType:'',dashDir:-1,dashTime:0,contact:0};notify('THE HOLLOW KING · Jump the shockwaves. Dodge the marked charge.');updateUI();save();}
function updateBoss(dt){const b=state.boss,p=state.player;if(!b||b.hp<=0)return;b.phase=b.hp<=b.maxHp*.5?2:1;b.contact=Math.max(0,b.contact-dt);b.timer-=dt;const dx=p.x-(b.x+30);
if(b.mode==='stalk'){b.vx=Math.abs(dx)>110?Math.sign(dx)*(b.phase===2?92:62):0;if(b.timer<=0){b.mode='tell';b.tell=b.phase===2?.65:.95;b.vx=0;b.attackType=(b.cycle||0)%2===0?'charge':'wave';b.cycle=(b.cycle||0)+1;b.dashDir=Math.sign(dx)||-1;}}
else if(b.mode==='tell'){b.vx=0;b.tell-=dt;if(b.tell<=0){if(b.attackType==='charge'){b.mode='charge';b.dashTime=b.phase===2?.8:.65;b.vx=b.dashDir*(b.phase===2?440:330);}else{b.mode='recover';b.timer=b.phase===2?1.2:1.7;for(const dir of [-1,1])projectiles.push({x:b.x+42,y:521,vx:dir*(b.phase===2?260:200),type:'wave',life:6});if(b.phase===2){const aim=Math.atan2(p.y+20-(b.y+30),p.x-(b.x+42));for(const spread of [-.22,0,.22])projectiles.push({x:b.x+42,y:b.y+30,vx:Math.cos(aim+spread)*180,vy:Math.sin(aim+spread)*180,type:'orb',life:5});}beep(110,.2,'triangle');}}}
else if(b.mode==='charge'){b.vx=b.dashDir*(b.phase===2?440:330);b.dashTime-=dt;if(b.dashTime<=0||b.x<=3670||b.x>=4690){b.mode='recover';b.vx=0;b.timer=b.phase===2?.9:1.4;}}
else if(b.mode==='recover'){b.vx=0;if(b.timer<=0){b.mode='stalk';b.timer=b.phase===2?1:1.5;}}
moveBody(b,dt,84,110);b.x=clamp(b.x,3660,4700);p.x=clamp(p.x,3650,4760);if(p.x+26>b.x+6&&p.x<b.x+78&&p.y+44>b.y+10&&p.y<b.y+110&&b.contact<=0){hurt(b.mode==='charge'?38:26);b.contact=1;}
for(const a of projectiles){a.x+=a.vx*dt;a.y+=(a.vy||0)*dt;a.life-=dt;const hit=a.type==='wave'?Math.abs(p.x+13-a.x)<30&&p.y+44>a.y-21:Math.hypot(p.x+13-a.x,p.y+20-a.y)<25;if(hit){hurt((a.type==='wave'?30:24)*(state.charm?.5:1));a.life=0;}}projectiles=projectiles.filter(a=>a.life>0&&a.x>3600&&a.x<4800);}
function updateUI(){if(!state)return;const p=state.player;$('hpText').textContent=Math.ceil(p.hp);$('hpBar').style.width=`${p.hp}%`;$('fuelText').textContent=Math.ceil(state.fuel);$('fuelBar').style.width=`${state.fuel}%`;for(const k of ['wood','stone','crystal','berry','iron','essence'])$(k).textContent=state.bag[k];$('phase').textContent=state.bossDefeated?'A NEW DAWN':state.boss?'THE FINAL CHALLENGE':`${state.night?'NIGHT':'DAY'} ${String(state.day).padStart(2,'0')}`;$('clock').textContent=state.bossDefeated?'Victory':state.boss?'Hollow King':`${state.night?'Dawn in':'Daylight ·'} ${Math.ceil((state.night?NIGHT:DAY)-state.time)}s`;$('nights').textContent=Array.from({length:3},(_,i)=>i<state.nights?'●':'○').join(' ');$('region').textContent=p.x<1250?'THE HOLLOW':p.x<2380?'MOSSWOOD RIDGE':p.x<3450?'THE CRYSTAL REACH':'THE FAR PINES';$('objective').textContent=state.bossDefeated?'The wild is yours.':state.boss?'Defeat the Hollow King':state.bossUnlocked?'Forge gear. Find the altar.':state.night?`Night ${state.day} · shadows grow stronger`:'Prepare for the Hollow King';$('eat').disabled=state.bag.berry<1||p.hp>=100;$('equip').textContent=state.equipped==='axe'?'⚒ Axe ⇄':state.equipped==='duskblade'?'† Duskblade ⇄':'† Sword ⇄';$('equip').setAttribute('aria-label',`Equipped ${weapons[state.equipped]?.name||'axe'}. Swap weapon.`);$('bossHud').hidden=!state.boss||state.boss.hp<=0;$('bossFill').style.width=`${state.boss?state.boss.hp/state.boss.maxHp*100:0}%`;$('bossHP').textContent=state.boss?`${Math.ceil(state.boss.hp)} / ${state.boss.maxHp}`:'';$('bossTell').textContent=state.boss?state.boss.mode==='tell'?(state.boss.attackType==='charge'?'CHARGE INCOMING — JUMP!':'SHOCKWAVE — GET OFF THE GROUND!'):state.boss.phase===2?'ENRAGED · Phase II':'Watch. Dodge. Strike.':'';
const off=CAMP<camera||CAMP>camera+viewW;$('campMarker').hidden=!off||!playing||!!state.boss;$('campMarker').textContent=CAMP<camera?'← Camp':'Camp →';$('campMarker').style.left=CAMP<camera?'12px':'auto';$('campMarker').style.right=CAMP<camera?'auto':'12px';}
function updateContext(){const p=state.player,r=getNearby();const altar=near(p.x,ALTAR,150)&&p.y>420;const gap=[1250,2380,3450].find(x=>Math.abs(p.x-x)<110&&!state.bridges.includes(x));const contextKey=state.boss?'boss':altar?'altar:'+state.bossUnlocked+state.duskblade+state.armor:gap!==undefined?'bridge:'+gap:r?'resource:'+r.id+state.equipped:near(p.x,CAMP,150)&&p.y>400?'camp':'';if($('context').dataset.key===contextKey)return;$('context').dataset.key=contextKey;$('context').replaceChildren();if(state.boss)return;if(gap!==undefined||altar){const btn=document.createElement('button');btn.textContent=altar?state.bossUnlocked?(state.duskblade&&state.armor?'Challenge the Hollow King [R]':'Altar · Requires Duskblade + Shadowmail'):'Sealed altar · Survive 3 nights':'Bridge · 3 wood [F]';btn.style.cssText='border:0;background:none;color:inherit;font:inherit;pointer-events:auto;padding:2px;';btn.onclick=altar?summonBoss:bridge;$('context').append(btn);}else $('context').textContent=r?`Hold Action / E · ${r.type==='wood'?'gather wood':r.type==='stone'?'mine stone':r.type==='iron'?'mine iron ore':r.type==='berry'?'pick berries':'collect crystal'}${state.equipped!=='axe'&&['wood','stone','iron'].includes(r.type)?' · equip axe':''}`:near(p.x,CAMP,150)&&p.y>400?'Your camp · Build / B':'';}
function update(dt){if(!playing||paused||ended)return;const p=state.player;if(!state.boss){state.time+=dt;if(state.time>=(state.night?NIGHT:DAY)){state.time=0;state.night=!state.night;if(!state.night){state.nights++;state.day++;enemies.forEach(e=>{if(e.hp<=0)dropShadow(e);});enemies=[];resources.forEach(r=>r.left=r.uses);if(state.nights>=3){state.bossUnlocked=true;notify('The altar awakens in the Far Pines. Forge your Duskblade and Shadowmail.');}else notify(`Dawn ${state.day}. Mine ore. Forge gear. The next night will be harder.`);p.hp=Math.min(100,p.hp+15);}else{spawnTime=1.4;notify(`Night ${state.day}: ${84+16*(state.day-1)}+ health shadows. Faster. Stronger. Stay ready.`);beep(130,.5,'triangle');}save();}state.fuel=Math.max(0,state.fuel-dt*(state.night?.8:.025));}
const dir=(keys.right?1:0)-(keys.left?1:0);p.vx=dir*230;if(dir)p.dir=dir;p.cool=Math.max(0,p.cool-dt);p.swing=Math.max(0,p.swing-dt);p.inv=Math.max(0,p.inv-dt);jumpBuffer=Math.max(0,jumpBuffer-dt);coyote=Math.max(0,coyote-dt);
if(jumpBuffer>0&&(p.jumps<2||coyote>0)){if(coyote>0)p.jumps=0;p.vy=p.jumps===0?-465:-430;p.jumps++;jumpBuffer=0;coyote=0;beep(p.jumps===1?320:450,.08,'triangle');puff(p.x+12,p.y+42,'#afbb8c',5);}
const grounded=moveBody(p,dt,26,44);if(grounded){p.jumps=0;coyote=.1;}else if(p.jumps===0&&coyote<=0)p.jumps=1;
if(p.y>840){p.inv=0;hurt(20);p.x=state.boss?4050:CAMP+35;p.y=470;p.vy=0;p.jumps=0;notify('A rough landing. −20 health.');}
if(state.shelter&&near(p.x,CAMP,140)&&state.fuel>0&&p.y>450&&!state.boss)p.hp=Math.min(100,p.hp+dt*1.8);
if(keys.action)doAction();if(ended)return;
if(state.night&&!state.boss){spawnTime-=dt;if(spawnTime<=0&&enemies.length<10){spawnTime=rand(5.8,8)/Math.sqrt(state.day);spawnShadow();}}
for(const e of enemies){e.attack=Math.max(0,e.attack-dt);e.stun=Math.max(0,e.stun-dt);const dist=p.x-e.x;e.dash-=dt;if(e.windup>0){e.windup-=dt;e.vx=0;if(e.windup<=0){e.dashTime=.35;e.dashDir=Math.sign(dist)||1;}}else if(e.dashTime>0){e.dashTime-=dt;e.vx=e.dashDir*(220+state.day*15);}else{e.vx=Math.sign(dist)*e.speed;if(state.day>=2&&e.dash<=0&&Math.abs(dist)<330){e.windup=.45;e.dash=rand(4,6);}}if(e.stun>0)e.vx=0;const groundedE=moveBody(e,dt,30,31);if(groundedE&&p.y+44<e.y-20&&Math.abs(dist)<280)e.vy=-430;const ahead=e.x+15+Math.sign(dist)*48;if(groundedE&&!allTerrain().some(t=>t.h>100&&ahead>t.x&&ahead<t.x+t.w)){e.vy=-430;e.dashTime=.65;e.dashDir=Math.sign(dist)||1;}const fireRadius=state.beacon?220:110;if(state.fuel>0&&near(e.x,CAMP,fireRadius)&&e.y>400){e.hp-=dt*(state.beacon?18:9);if(Math.random()<dt*5)puff(e.x,e.y,'#e8bd7e',2);}if(Math.abs(e.x-p.x)<29&&Math.abs(e.y-p.y)<38&&e.attack<=0){hurt(e.damage+(e.dashTime>0?4:0));e.attack=1;}if(e.hp<=0)dropShadow(e);if(e.y>880){e.hp=0;dropShadow(e);}}
enemies=enemies.filter(e=>e.hp>0);collectLoot(dt);updateBoss(dt);for(const r of resources)r.flash=Math.max(0,r.flash-dt);camera+=(clamp(p.x-viewW*.4,0,Math.max(0,W-viewW))-camera)*Math.min(1,dt*6);updateContext();saveTime+=dt;if(saveTime>5){saveTime=0;save();}updateUI();}
// Art is drawn locally: layered mountains, wind-shaped pines, mossy platforms and a tiny traveller.
function poly(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill();}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}
function pine(x,y,h,c,detail=false){ctx.fillStyle=c;ctx.fillRect(x-3,y-h*.7,6,h*.7);for(let i=0;i<4;i++){const ty=y-h+i*h*.17;const w=h*(.15+i*.035);poly([[x,ty],[x-w,ty+h*.38],[x+w,ty+h*.38]],c);}if(detail){ctx.strokeStyle='#a6b59214';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y-h+10);ctx.lineTo(x-2,y-12);ctx.stroke();}}
function background(n){const grad=ctx.createLinearGradient(0,0,0,viewH);grad.addColorStop(0,n?'#152d3a':'#527568');grad.addColorStop(.65,n?'#304941':'#90a68a');grad.addColorStop(1,n?'#3b5145':'#c4c3a0');ctx.fillStyle=grad;ctx.fillRect(0,0,viewW,viewH);
if(n){for(let i=0;i<60;i++){const x=(i*173.7-camera*.04)%(viewW+200);const y=20+(i*91.1)%(viewH*.5);ctx.globalAlpha=.3+(Math.sin(anim*.6+i)+1)*.18;ellipse(x,y,1,1,'#f1e6c2');}ctx.globalAlpha=1;ellipse(viewW*.77,viewH*.17,25,25,'#d6d8b3');ellipse(viewW*.77+11,viewH*.17-6,24,24,'#1b3340');}else{const glow=ctx.createRadialGradient(viewW*.73,viewH*.17,0,viewW*.73,viewH*.17,170);glow.addColorStop(0,'#eddcaa66');glow.addColorStop(1,'#ddd6ac00');ctx.fillStyle=glow;ctx.fillRect(0,0,viewW,viewH);ellipse(viewW*.73,viewH*.17,27,27,'#e5d2a1');}
for(let layer=0;layer<3;layer++){let pts=[[0,viewH]];for(let x=-100;x<=viewW+100;x+=45){const q=x+camera*(.04+layer*.055);const y=viewH*(.47+layer*.12)+Math.sin(q*.003+layer*3)*45+Math.cos(q*.008+layer)*23;pts.push([x,y]);}pts.push([viewW,viewH]);poly(pts,n?['#284846','#2c5148','#335b4a'][layer]:['#6d8d78','#62846e','#4f775e'][layer]);}
for(let i=0;i<36;i++){const x=i*116-camera*.23;const xx=((x%(viewW+300))+(viewW+300))%(viewW+300)-150;const h=100+(i*47)%170;pine(xx,viewH*.95,h,n?'#27483c':'#3d654e');}
ctx.fillStyle=n?'#173e2c33':'#d7d6a51a';ctx.fillRect(0,viewH*.7,viewW,viewH*.3);
for(let i=0;i<10;i++){const x=((i*191+anim*6-camera*.1)%(viewW+160))-80;const y=80+(i*47)%(viewH-80)+Math.sin(anim*.5+i)*12;ellipse(x,y,2,1,'#e4d6aa35');}}
function drawTerrain(p){const x=p.x-camera,y=p.y;if(x+p.w<0||x>viewW)return;if(p.bridge){ctx.fillStyle='#917d54';ctx.fillRect(x,y,p.w,13);ctx.fillStyle='#4c4d35';for(let i=0;i<p.w;i+=16)ctx.fillRect(x+i,y,2,13);return;}const ground=p.h>100;ctx.fillStyle=ground?'#344136':'#495341';ctx.fillRect(x,y,p.w,p.h);ctx.fillStyle='#738568';ctx.fillRect(x,y,p.w,8);ctx.fillStyle='#a4af7c';ctx.fillRect(x,y,p.w,3);ctx.fillStyle='#28392f';ctx.fillRect(x,y+12,p.w,ground?9:5);if(!ground){poly([[x,y+25],[x+p.w*.15,y+50],[x+p.w*.36,y+39],[x+p.w*.65,y+61],[x+p.w,y+25]],'#354536');for(let i=0;i<3;i++){ctx.strokeStyle='#81946c';ctx.beginPath();ctx.moveTo(x+30+i*47,y+30);ctx.quadraticCurveTo(x+15+i*48,y+58,x+35+i*47,y+66);ctx.stroke();}}for(let i=0;i<p.w;i+=17){const h=4+((i*13)%9);ctx.strokeStyle=i%3?'#8f9e70':'#b5b989';ctx.beginPath();ctx.moveTo(x+i,y);ctx.lineTo(x+i-3,y-h);ctx.moveTo(x+i,y);ctx.lineTo(x+i+2,y-h-2);ctx.stroke();}if(ground){ctx.fillStyle='#89947717';for(let i=0;i<p.w;i+=39)ctx.fillRect(x+i+9,y+35+(i%29),12,3);}}
function treeResource(r){const x=r.x-camera,y=r.y;const h=120+(r.id*23)%65;if(r.left<=0){ctx.fillStyle='#706043';ctx.fillRect(x-9,y-13,18,13);ellipse(x,y-13,9,3,'#a59468');return;}ctx.save();ctx.translate(x+(r.flash>0?Math.sin(anim*80)*3:0),y);ctx.fillStyle='#716544';ctx.fillRect(-7,-h*.58,14,h*.58);ctx.fillStyle='#9b8a5d';ctx.fillRect(-7,-h*.58,3,h*.58);for(let i=0;i<4;i++){const top=-h+i*h*.17;const width=h*(.19+i*.04);poly([[0,top],[-width,top+h*.37],[-width*.6,top+h*.35],[width,top+h*.37]],['#274c35','#315b3e','#3e6744','#557a4e'][i]);}ctx.restore();}
function drawResource(r){const x=r.x-camera,y=r.y;if(x<-150||x>viewW+150)return;if(r.type==='wood'){treeResource(r);return;}if(r.left<=0)return;if(r.type==='stone'||r.type==='iron'){poly([[x-24,y],[x-29,y-13],[x-14,y-33],[x+10,y-35],[x+29,y-10],[x+22,y]],r.flash?'#c2c9ae':'#8b9c8b');poly([[x-14,y-33],[x+10,y-35],[x+1,y-13],[x-29,y-13]],'#a7b4a0');poly([[x+1,y-13],[x+10,y-35],[x+29,y-10],[x+22,y]],'#728c7c');if(r.type==='iron'){ctx.strokeStyle='#e6ad7e';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x-16,y-17);ctx.lineTo(x-4,y-27);ctx.lineTo(x+7,y-15);ctx.lineTo(x+17,y-24);ctx.stroke();ctx.fillStyle='#e6b18b';ctx.fillRect(x-11,y-11,5,4);}}else if(r.type==='berry'){ellipse(x,y-13,29,16,'#375a36');ellipse(x-13,y-22,17,15,'#466b3e');ellipse(x+12,y-23,18,14,'#507642');for(let i=0;i<6;i++)ellipse(x-19+(i*13)%39,y-10-(i*7)%23,3.5,3.5,'#c58a7b');}else{const b=Math.sin(anim*2+r.id)*3;const glow=ctx.createRadialGradient(x,y-19,2,x,y-19,50);glow.addColorStop(0,'#a1edc93a');glow.addColorStop(1,'#a1edc900');ctx.fillStyle=glow;ctx.fillRect(x-50,y-69,100,100);poly([[x,y-39+b],[x-11,y-21+b],[x,y-3+b],[x+11,y-21+b]],'#aed5b6');poly([[x,y-39+b],[x,y-3+b],[x+11,y-21+b]],'#6fac99');ctx.fillStyle='#e2edd0';ctx.fillRect(x-2,y-30+b,2,8);}}
function drawCamp(){const x=CAMP-camera,y=GROUND;if(state.shelter){poly([[x-105,y],[x-66,y-81],[x-27,y]],'#bca878');poly([[x-66,y-81],[x-27,y],[x-5,y]],'#8d885d');poly([[x-75,y],[x-65,y-52],[x-50,y]],'#354936');ctx.strokeStyle='#e4d4a2';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-108,y);ctx.lineTo(x-65,y-84);ctx.lineTo(x-23,y);ctx.stroke();}else{ctx.strokeStyle='#8f9c73';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-100,y);ctx.lineTo(x-80,y-34);ctx.lineTo(x-60,y);ctx.stroke();ctx.setLineDash([3,4]);ctx.strokeStyle='#9aa77c66';ctx.strokeRect(x-110,y-65,60,65);ctx.setLineDash([]);}
if(state.beacon){ctx.fillStyle='#768d73';ctx.fillRect(x+65,y-95,10,95);poly([[x+70,y-123],[x+57,y-104],[x+70,y-84],[x+83,y-104]],'#adedd1');}
if(state.fuel>0){const radius=state.beacon?245:155;const glow=ctx.createRadialGradient(x,y-20,5,x,y-20,radius);glow.addColorStop(0,'#e9b97533');glow.addColorStop(1,'#e9b97500');ctx.fillStyle=glow;ctx.fillRect(x-radius,y-radius-20,radius*2,radius*2);for(let i=0;i<4;i++){const f=Math.sin(anim*8+i*3)*5;poly([[x-13+i*5,y-9],[x-7+i*4,y-48+f+i*4],[x+8+i*3,y-9]],['#b77541','#e39c4e','#e9c579','#f0d89b'][i]);}for(let i=0;i<6;i++){const t=(anim*.7+i*.17)%1;ellipse(x+Math.sin(i*6+anim)*t*20,y-20-t*70,1.5*(1-t),2*(1-t),'#f3d08b');}}
ctx.strokeStyle='#785d40';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(x-19,y-2);ctx.lineTo(x+17,y-12);ctx.moveTo(x-18,y-13);ctx.lineTo(x+20,y-2);ctx.stroke();for(let i=0;i<6;i++)ellipse(x-26+i*10,y+2+Math.sin(i)*2,5,3,'#8d9580');ctx.font='8px Arial';ctx.textAlign='center';ctx.fillStyle='#d4d3a6';ctx.fillText('C A M P',x,y+25);}
function drawPlayer(p){const x=p.x-camera,y=p.y;ctx.save();ctx.translate(x+13,y+23);if(p.inv>0&&Math.floor(anim*14)%2===0)ctx.globalAlpha=.5;ctx.scale(p.dir,1);const step=Math.abs(p.vx)>0?Math.sin(anim*16)*6:0;ctx.fillStyle='#384c3c';ctx.fillRect(-9,8,7,14+step*.5);ctx.fillRect(2,8,7,14-step*.5);ctx.fillStyle='#b6a47d';ctx.fillRect(-10,18+step*.5,9,4);ctx.fillRect(1,18-step*.5,10,4);poly([[-10,-9],[9,-8],[12,12],[-12,12]],state.armor?'#76778f':'#b4744b');poly([[-9,-8],[-18,-3-Math.sin(anim*5)*2],[-12,9],[-3,6]],'#d2a66c');ctx.fillStyle='#54624b';ctx.fillRect(-13,-6,7,17);ctx.fillStyle='#e4c79a';ctx.fillRect(-7,-22,15,13);ctx.fillStyle='#554d37';ctx.fillRect(-8,-24,15,6);ctx.fillRect(-10,-22,5,10);ctx.fillStyle='#263a2e';ctx.fillRect(4,-17,2,2);ctx.fillStyle='#ddd0a1';ctx.fillRect(-9,-11,19,5);ctx.save();ctx.translate(8,0);ctx.rotate(p.swing>0?-1.4+p.swing*12:.3);ctx.strokeStyle='#b6a276';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,6);ctx.lineTo(0,-17);ctx.stroke();if(state.equipped==='axe'){poly([[-1,-17],[11,-20],[14,-11],[0,-9]],state.axe?'#e5e2bd':'#9cae98');}else{poly([[0,-40],[-5,-30],[-3,0],[3,0],[5,-30]],state.equipped==='duskblade'?'#cdb7ee':'#c1d3c6');ctx.fillStyle='#d5b980';ctx.fillRect(-8,-3,16,3);}ctx.restore();if(p.swing>0){ctx.strokeStyle='#ebd9a36b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(10,-3,34,-1.5,1.2);ctx.stroke();}ctx.restore();}
function drawEnemy(e){const x=e.x-camera,y=e.y;const bob=Math.sin(anim*6+e.seed)*2;ellipse(x+15,y+29,20,4,'#102d2266');poly([[x-2,y+26],[x+3,y+5+bob],[x+15,y-2+bob],[x+29,y+8+bob],[x+33,y+28],[x+23,y+24],[x+15,y+31],[x+6,y+25]],e.brute?'#423b4b':'#203c35');if(e.brute){poly([[x+2,y+10],[x-8,y-7],[x+12,y+3]],'#837382');poly([[x+22,y+3],[x+37,y-7],[x+29,y+12]],'#837382');}ctx.fillStyle=e.windup>0?'#ffaf86':'#ddbc87';ctx.fillRect(x+8,y+11+bob,4,3);ctx.fillRect(x+20,y+11+bob,4,3);if(e.hp<e.maxHp){ctx.fillStyle='#132c2b';ctx.fillRect(x-3,y-11,36,3);ctx.fillStyle='#c5a8bc';ctx.fillRect(x-3,y-11,36*Math.max(0,e.hp/e.maxHp),3);}if(e.windup>0){ctx.strokeStyle='#efb18d';ctx.beginPath();ctx.arc(x+15,y+15,24,0,Math.PI*2);ctx.stroke();}}
function draw(dt){anim+=dt;background(state.night);ctx.save();const worldOffset=viewH-GROUND-62+Math.max(0,(GROUND-44)-state.player.y-viewH*.45);ctx.translate(0,worldOffset);for(const p of allTerrain())drawTerrain(p);for(const r of resources)drawResource(r);drawCamp();drawAltar();drawLoot();drawProjectiles();drawBoss();for(const e of enemies)drawEnemy(e);drawPlayer(state.player);
for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;ctx.globalAlpha=Math.max(0,p.life*1.5);ctx.fillStyle=p.color;ctx.fillRect(p.x-camera,p.y,p.size,p.size);}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);for(const f of floaters){f.life-=dt;f.y-=dt*25;ctx.globalAlpha=clamp(f.life,0,1);ctx.font='11px Arial';ctx.textAlign='center';ctx.fillStyle=f.color;ctx.fillText(f.text,f.x-camera,f.y);}ctx.globalAlpha=1;floaters=floaters.filter(f=>f.life>0);ctx.restore();const vignette=ctx.createLinearGradient(0,0,0,viewH);vignette.addColorStop(0,'#14352a22');vignette.addColorStop(.65,'#12342500');vignette.addColorStop(1,'#11291f88');ctx.fillStyle=vignette;ctx.fillRect(0,0,viewW,viewH);}
function drawAltar(){const x=ALTAR-camera,y=GROUND;if(x<-100||x>viewW+100)return;ctx.fillStyle='#596b68';ctx.fillRect(x-38,y-12,76,12);ctx.fillStyle='#70867e';ctx.fillRect(x-22,y-36,44,25);poly([[x-36,y-40],[x,y-57],[x+36,y-40],[x,y-30]],'#7e9390');const c=state.bossUnlocked?'#c3a8e6':'#6b8883';poly([[x,y-100+Math.sin(anim*2)*4],[x-13,y-77],[x,y-57],[x+13,y-77]],c);if(state.bossUnlocked){const gl=ctx.createRadialGradient(x,y-78,0,x,y-78,100);gl.addColorStop(0,'#c8a1ed30');gl.addColorStop(1,'#c8a1ed00');ctx.fillStyle=gl;ctx.fillRect(x-100,y-178,200,200);}ctx.font='8px Arial';ctx.textAlign='center';ctx.fillStyle='#d6c6e3';ctx.fillText(state.bossUnlocked?'T H E  K I N G  A W A I T S':'T H E  S E A L E D  A L T A R',x,y+24);}
function drawBoss(){const b=state.boss;if(!b||b.hp<=0)return;const x=b.x-camera,y=b.y;ctx.save();ctx.translate(x+42,y+55);const pulse=Math.sin(anim*4)*3;ellipse(0,52,54,7,'#081c2799');poly([[-43,50],[-37,-30],[-20,-55],[17,-58],[37,-30],[47,49],[26,36],[9,54],[-9,39],[-27,52]],b.phase===2?'#302d47':'#243b3c');poly([[-28,-53],[-34,-80],[-12,-65],[0,-87],[13,-65],[33,-80],[27,-51]],'#b2a0bd');poly([[-30,-17],[-10,-23],[-13,-12]],'#f6cba8');poly([[11,-23],[31,-17],[14,-12]],'#f6cba8');poly([[0,-1+ pulse],[-11,18],[0,34],[11,18]],b.phase===2?'#e1a1c2':'#acbadd');ctx.strokeStyle=b.mode==='tell'?'#e8ac92':'#797d9b';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(-36,-13);ctx.lineTo(-56,21);ctx.moveTo(36,-13);ctx.lineTo(58,23);ctx.stroke();ctx.restore();
if(b.mode==='tell'){ctx.strokeStyle=b.attackType==='charge'?'#f1b28c':'#c6b6f4';ctx.lineWidth=3;ctx.setLineDash([9,7]);ctx.beginPath();if(b.attackType==='charge'){ctx.moveTo(x+42,y+95);ctx.lineTo(x+42+b.dashDir*340,y+95);}else{ctx.moveTo(3650-camera,GROUND-9);ctx.lineTo(4800-camera,GROUND-9);}ctx.stroke();ctx.setLineDash([]);}}
function drawLoot(){for(const l of loot){const x=l.x-camera;if(x<-40||x>viewW+40)continue;const y=l.y+Math.sin(anim*4+l.x)*3;if(l.type==='essence'){ellipse(x,y,10,10,'#b39bd52e');poly([[x,y-9],[x-6,y],[x,y+9],[x+6,y]],'#c4a8e8');}else ellipse(x,y,4,4,'#da9a8c');}}
function drawProjectiles(){for(const p of projectiles){const x=p.x-camera;if(p.type==='wave'){poly([[x-20,p.y+6],[x-4,p.y-20],[x+5,p.y-28],[x+20,p.y+6]],'#b5aad7');}else{ellipse(x,p.y,11,11,'#c6a4e333');ellipse(x,p.y,6,6,'#d6b9eb');}}}
function launchFirework(x=rand(.12,.88)*viewW,y=rand(.14,.62)*viewH){const color=['#f7ce7f','#c5e4c1','#d6b4f3','#edacb2','#a9d9ef'][Math.floor(rand(0,5))];for(let i=0;i<48;i++){const angle=i/48*Math.PI*2,speed=rand(42,130);fireworks.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:rand(.9,1.7),color});}beep(rand(180,290),.14,'triangle',.018);}
function drawFireworks(dt){const c=$('celebration'),f=c.getContext('2d');f.clearRect(0,0,viewW,viewH);if(!celebration)return;fireworkTimer-=dt;if(fireworkTimer<=0){launchFirework();fireworkTimer=.55;}for(const p of fireworks){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=28*dt;p.vx*=Math.pow(.985,dt*60);f.globalAlpha=clamp(p.life,0,1);f.strokeStyle=p.color;f.lineWidth=2;f.beginPath();f.moveTo(p.x,p.y);f.lineTo(p.x-p.vx*.055,p.y-p.vy*.055);f.stroke();}f.globalAlpha=1;fireworks=fireworks.filter(p=>p.life>0);}
function resize(){const rect=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);scale=rect.height<260?.60:rect.width<550?.85:1;viewW=rect.width/scale;viewH=rect.height/scale;ctx.setTransform(dpr*scale,0,0,dpr*scale,0,0);const f=$('celebration');f.width=canvas.width;f.height=canvas.height;f.getContext('2d').setTransform(dpr*scale,0,0,dpr*scale,0,0);}
function frame(t){const dt=Math.min((t-last)/1000||.016,.04);last=t;if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').classList.remove('show');}update(dt);draw(dt);drawFireworks(dt);requestAnimationFrame(frame);}
window.addEventListener('resize',resize);document.addEventListener('fullscreenchange',resize);
const keyMap={a:'left',ArrowLeft:'left',d:'right',ArrowRight:'right',e:'action'};
document.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;const k=e.key.length===1?e.key.toLowerCase():e.key;if([' ','ArrowUp','ArrowLeft','ArrowRight','ArrowDown'].includes(k))e.preventDefault();if($('guide').open){if(k==='Escape')$('guide').close();return;}if(k==='Escape'){if(!$('buildOverlay').hidden)closeBuild();else if(!$('inventoryOverlay').hidden)closeInventory();else togglePause();return;}if(k==='i'&&!e.repeat){if(!$('inventoryOverlay').hidden)closeInventory();else if(!paused)openInventory();return;}if(anyMenu()){if(k==='q')eat();return;}if(keyMap[k])keys[keyMap[k]]=true;if(k==='e')doAction();if(e.repeat)return;if(k===' '||k==='w'||k==='ArrowUp')jump();if(k==='q')eat();if(k==='b'&&!paused)openBuild();if(k==='1')equip('axe');if(k==='2')equip(state.duskblade?'duskblade':'sword');if(k==='x')swapWeapon();if(k==='r')summonBoss();if(k==='f')bridge();if(k==='p')togglePause();});
document.addEventListener('keyup',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;if(keyMap[k])keys[keyMap[k]]=false;});
const heldPointers=new Map();document.querySelectorAll('[data-hold]').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);const k=btn.dataset.hold;heldPointers.set(e.pointerId,k);btn.classList.add('active');if(k==='jump')jump();else{keys[k]=true;if(k==='action')doAction();}});const up=e=>{const k=heldPointers.get(e.pointerId);heldPointers.delete(e.pointerId);if(k)keys[k]=[...heldPointers.values()].includes(k);btn.classList.remove('active');};btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up);});
window.addEventListener('blur',()=>{keys={};if(playing&&!ended&&!anyMenu())togglePause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys={};save();if(playing&&!ended&&!anyMenu())togglePause(true);}});
$('start').onclick=()=>init();const saved=readSave();if(saved){$('continue').hidden=false;$('continue').onclick=()=>init(readSave()||fresh());$('start').textContent='Start a new adventure →';}
$('pause').onclick=()=>togglePause();$('resume').onclick=()=>togglePause(false);$('restart').onclick=()=>{if(!restartArmed){restartArmed=true;$('restartHint').hidden=false;return;}restartArmed=false;$('restartHint').hidden=true;init();};$('again').onclick=()=>init();$('eat').onclick=eat;$('bagEat').onclick=eat;$('build').onclick=()=>{if(!paused)openBuild();};$('closeBuild').onclick=closeBuild;$('inventoryButton').onclick=()=>{if(!paused)openInventory();};$('closeInventory').onclick=closeInventory;$('equip').onclick=()=>{if(!paused)swapWeapon();};
$('guideButton').onclick=()=>{dialogPause=paused;if(playing&&!ended&&!anyMenu())togglePause(true);$('guide').showModal();};$('closeGuide').onclick=()=>$('guide').close();$('guide').addEventListener('close',()=>{if(playing&&!ended&&!anyMenu()&&!dialogPause)togglePause(false);});
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Mute game sound':'Enable game sound');beep(500,.15);};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('shell').requestFullscreen();resize();}catch{notify('Fullscreen is unavailable in this browser. Try landscape.');}};
window.addEventListener('pagehide',save);
state=fresh();state.player.x=560;state.player.y=GROUND-44;resize();camera=0;updateUI();requestAnimationFrame(frame);
})();
